                writer.WritePropertyName("charges");
                JsonSerializer.Serialize(writer, creditNoteTemplateRequest.Charges, jsonSerializerOptions);
            }
            if (creditNoteTemplateRequest.NoteOption.IsSet)
                writer.WriteString("note", creditNoteTemplateRequest.Note);
        }
    }
}
